mapper.select:
SELECT TO_CHAR(t1.TR_YMD, 'YYYY-MM-DD') AS tr_ymd , t1.FUND_CD AS fund_cd , ia.FUND_NM AS fund_nm , t1.TR_CD AS tr_cd , F_TR_NM(t1.TR_CD) AS tr_nm , t1.JM_CD AS jm_cd , hj.HJ_NM AS hj_nm , t1.AEKM AS aekm , t1.SANGHW_AEK AS sanghw_aek , t1.TR_AEK AS tr_aek , t1.MK_SUIK_RT * 100 AS suik_per , NVL(t1.SUSU_GA, 0) + NVL(t1.SUSU_09900, 0) AS susu , CASE WHEN t1.TR_CD LIKE 'J%' THEN 0 ELSE kk.CHUI_AEK END AS chui_aek , CASE WHEN t1.TR_CD LIKE 'J%' THEN 0 ELSE kk.SUIP_IJA END AS suip_ija , t1.MM_SONIK AS mm_sonik , t1.MIJIGUB_TAX AS mijigub_tax , CASE WHEN t1.TR_CD LIKE 'J%' THEN t1.TR_AEK + NVL(t1.SUSU_GA, 0) + NVL(t1.SUSU_09900, 0) + NVL(t1.MIJIGUB_TAX, 0) ELSE t1.TR_AEK - NVL(t1.SUSU_GA, 0) - NVL(t1.SUSU_09900, 0) - NVL(t1.MIJIGUB_TAX, 0) END AS jungsan_aek , TO_CHAR(hj.BALH_YMD, 'YYYY-MM-DD') AS balh_ymd , TO_CHAR(hj.SANGHW_YMD, 'YYYY-MM-DD') AS sanghw_ymd , hj.PYOM_IYUL * 100 AS pyom_per , SUBSTR(t1.TR_CD, 1, 1) AS tr_color FROM SHT0HG t1 , SHM1K kk , SZM0IA ia , SHM0HJ hj WHERE t1.CORP_GR = #{corpGr} AND t1.TR_YMD BETWEEN TO_DATE(#{fYmd}, 'YYYY-MM-DD') AND TO_DATE(#{tYmd}, 'YYYY-MM-DD')
AND t1.FUND_CD = #{fundCd}
AND kk.CORP_GR(+) = t1.CORP_GR AND kk.YMD(+) = t1.TR_YMD AND kk.FUND_CD(+) = t1.FUND_CD AND kk.JM_CD(+) = t1.JM_CD AND ia.CORP_GR = t1.CORP_GR AND ia.FUND_CD = t1.FUND_CD AND hj.CORP_GR = t1.CORP_GR AND hj.JM_CD = t1.JM_CD ORDER BY t1.FUND_CD, t1.TR_YMD, t1.TR_CD
